import 'dart:io';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:nothingness/models/audio_track.dart';
import 'package:nothingness/models/screen_config.dart';
import 'package:nothingness/models/song_info.dart';
import 'package:nothingness/widgets/heroes/dot_hero.dart';

import '_test_helpers.dart';

const _fixturePath = '/opt/nothingness/media/01-undercover-49.opus';
const _artistLong =
    'A Very Long Artist Name That Should Ellipsize Correctly And Never Clip';
const _titleLong =
    'A Very Long Song Title That Should Ellipsize Correctly And Never Clip';

Future<void> _capturePng({
  required WidgetTester tester,
  required String outPath,
  double pixelRatio = 1.0,
  required Finder boundary,
}) async {
  final renderObject = tester.renderObject(boundary);
  if (renderObject is! RenderRepaintBoundary) {
    throw StateError('Expected RenderRepaintBoundary at $boundary');
  }

  final image = await renderObject.toImage(pixelRatio: pixelRatio);
  final byteData = await image.toByteData(format: ui.ImageByteFormat.png);
  image.dispose();
  final pngBytes = byteData?.buffer.asUint8List();
  if (pngBytes == null) throw StateError('toByteData returned null');

  final f = File(outPath);
  await f.parent.create(recursive: true);
  await f.writeAsBytes(pngBytes, flush: true);
}

void main() {
  testWidgets('Dot hero show-song-info overlay screenshots (normal + max text size)',
      (tester) async {
    const heroSize = 400.0;

    // Common fake playback state — spectrum high so the dot reaches its max
    // allowed radius.
    final spectrum = List<double>.filled(8, 1.0);

    Future<void> pumpAndShot({
      required double textScale,
      required String out,
    }) async {
      final provider = FakeAudioPlayerProvider(
        spectrumData: spectrum,
        songInfo: SongInfo(
          track: AudioTrack(
            path: _fixturePath,
            title: _titleLong,
            artist: _artistLong,
          ),
          isPlaying: true,
          position: 0,
          duration: 200000,
        ),
      );

      const config = DotScreenConfig(showSongInfo: true);

      await tester.pumpWidget(
        wrapWithProvider(
          provider,
          RepaintBoundary(
            key: const ValueKey('dot-shot-boundary'),
            child: SizedBox(
              width: heroSize,
              height: heroSize,
              child: DotHero(
                config: config.copyWith(textScale: textScale),
              ),
            ),
          ),
        ),
      );

      // One extra pump to ensure the AnimatedBuilder has a rendered frame.
      await tester.pump();

      await _capturePng(
        tester: tester,
        boundary: find.byKey(const ValueKey('dot-shot-boundary')),
        outPath: out,
      );
    }

    await pumpAndShot(
      textScale: 1.0,
      out: '.tmp/agent_shots/dot_show_song_info_normal.png',
    );

    await pumpAndShot(
      textScale: 1.5,
      out: '.tmp/agent_shots/dot_show_song_info_max.png',
    );
  });
}

